import { describe, it, expect, vi } from "vitest";

describe("Carrinho", () => {
  it("calcula o total e notifica o callback", () => {
    const onCheckout = vi.fn();
    const item = { id: 1, preco: 50 };

    onCheckout(item.preco);
    expect(item).toEqual({ id: 1, preco: 50 });
    expect(onCheckout).toHaveBeenCalledWith(50);
  });
});
